1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"strings"
12		"sync"
13		"testing"
14	)
15	
16	func i64p(v int64) *int64 { return &v }
17	
18	func intent(id, account, asset string, amount int64) PaymentIntent {
19		return PaymentIntent{ID: id, Account: account, Paymaster: "pm", Asset: asset, Amount: i64p(amount), Nonce: 1, State: "pending"}
20	}
21	
22	func newTestLedger(t *testing.T, init []BalanceInit) string {
23		t.Helper()
24		path := filepath.Join(t.TempDir(), "ledger.json")
25		if err := CreateLedger(path, init); err != nil {
26			t.Fatalf("CreateLedger: %v", err)
27		}
28		return path
29	}
30	
31	func openOrFail(t *testing.T, path string) *Ledger {
32		t.Helper()
33		l, err := Open(path)
34		if err != nil {
35			t.Fatalf("Open: %v", err)
36		}
37		t.Cleanup(func() { l.Close() })
38		return l
39	}
40	
41	func statuses(r *BatchResult) []string {
42		out := make([]string, len(r.Results))
43		for i, x := range r.Results {
44			out[i] = x.Status
45		}
46		return out
47	}
48	
49	// ---- 初始化校验 ----
50	
51	func TestCreateValidation(t *testing.T) {
52		dir := t.TempDir()
53	
54		cases := []struct {
55			name string
56			init []BalanceInit
57		}{
58			{"empty account", []BalanceInit{{Account: "", Asset: "usdc", Balance: 1}}},
59			{"empty asset", []BalanceInit{{Account: "aa", Asset: "", Balance: 1}}},
60			{"negative balance", []BalanceInit{{Account: "aa", Asset: "usdc", Balance: -1}}},
61			{"duplicate entry", []BalanceInit{
62				{Account: "aa", Asset: "usdc", Balance: 1},
63				{Account: "aa", Asset: "usdc", Balance: 2},
64			}},
65		}
66		for _, tc := range cases {
67			t.Run(tc.name, func(t *testing.T) {
68				path := filepath.Join(dir, tc.name+".json")
69				err := CreateLedger(path, tc.init)
70				if err == nil || KindOf(err) != ErrInvalid {
71					t.Fatalf("want ErrInvalid, got %v", err)
72				}
73				if _, statErr := os.Stat(path); !errors.Is(statErr, os.ErrNotExist) {
74					t.Fatalf("illegal init must not create a file, stat err=%v", statErr)
75				}
76			})
77		}
78	
79		// 合法初始化：0 与 MaxInt64 都是合法非负余额。
80		path := filepath.Join(dir, "ok.json")
81		if err := CreateLedger(path, []BalanceInit{
82			{Account: "aa", Asset: "usdc", Balance: 0},
83			{Account: "aa", Asset: "eth", Balance: math.MaxInt64},
84		}); err != nil {
85			t.Fatalf("valid init: %v", err)
86		}
87	
88		// 重复初始化报错，不覆盖。
89		err := CreateLedger(path, []BalanceInit{{Account: "bb", Asset: "usdc", Balance: 1}})
90		if err == nil || KindOf(err) != ErrExists {
91			t.Fatalf("re-init want ErrExists, got %v", err)
92		}
93		l := openOrFail(t, path)
94		if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
95			t.Fatalf("history overwritten: aa/usdc=%d", bal)
96		}
97		if bal, _ := l.Balance("bb", "usdc"); bal != 0 {
98			t.Fatalf("re-init leaked new account, bb/usdc=%d", bal)
99		}
100	}
101	
102	func TestOpenUninitializedAndMissing(t *testing.T) {
103		if _, err := Open(filepath.Join(t.TempDir(), "nope.json")); KindOf(err) != ErrNotInit {
104			t.Fatalf("want ErrNotInit, got %v", err)
105		}
106	}
107	
108	// ---- 手续费 ----
109	
110	func TestFeeFor(t *testing.T) {
111		cases := []struct {
112			amount int64
113			bps    int
114			want   int64
115		}{
116			{1, 1, 0}, // 1*1/10000 向下取整 = 0
117			{10000, 1, 1},
118			{1500, 30, 4}, // 45000/10000 = 4.5 -> 4
119			{900, 30, 2},  // 27000/10000 = 2.7 -> 2
120			{2000, 0, 0},
121			{2000, 10000, 2000},
122			{9999, 9999, 9998}, // 99980001/10000 = 9998.0001
123			{math.MaxInt64, 1, math.MaxInt64 / 10000}, // 大数不溢出
124		}
125		for _, tc := range cases {
126			if got := feeFor(tc.amount, tc.bps); got != tc.want {
127				t.Errorf("feeFor(%d,%d)=%d want %d", tc.amount, tc.bps, got, tc.want)
128			}
129		}
130	}
131	
132	// ---- 批次逐项结果与顺序语义 ----
133	
134	func TestBatchOrderedIndependentResults(t *testing.T) {
135		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 2000}})
136		l := openOrFail(t, path)
137	
138		res, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
