742	// TestLegacyExecuteLargeAmountNoOverflow 验证大额付款的手续费不再因中间乘积
743	// 溢出而算错：amount*feeBps 本身可能超过 int64，但只要最终总额可表示，
744	// 就按精确总额判断余额。
745	func TestLegacyExecuteLargeAmountNoOverflow(t *testing.T) {
746		const (
747			amount    = int64(4000000000000000000)
748			feeBps    = 30
749			wantFee   = int64(12000000000000000)
750			wantTotal = amount + wantFee // 4012000000000000000
751		)
752	
753		// 余额恰好等于总额：成功，扣款额精确，编号被标记。
754		spent := map[string]bool{}
755		s := Execute(Intent{ID: "big", State: "pending", Amount: amount}, feeBps, spent, wantTotal)
756		if s.Status != "settled" {
757			t.Fatalf("exact balance should settle: %+v", s)
758		}
759		if s.Charged != wantTotal {
760			t.Fatalf("charged=%d want %d", s.Charged, wantTotal)
761		}
762		if s.FeeBps != feeBps || s.Intent != "big" || s.Ref != "settle:big" {
763			t.Fatalf("settlement fields: %+v", s)
764		}
765		if !spent["big"] {
766			t.Fatalf("id must be marked after success")
767		}
768	
769		// 余额少一个最小单位：余额不足失败，不标记编号、不留引用、不报错扣款额。
770		spent = map[string]bool{}
771		s = Execute(Intent{ID: "big", State: "pending", Amount: amount}, feeBps, spent, wantTotal-1)
772		if s.Status != "failed" || s.Reason != reasonFunds {
773			t.Fatalf("one unit short should fail insufficient: %+v", s)
774		}
775		if s.Charged != 0 || s.Ref != "" {
776			t.Fatalf("failure must not charge or reference: %+v", s)
777		}
778		if spent["big"] {
779			t.Fatalf("failed id must not be marked")
780		}
781	}
