980			}
981		}
982		first, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "reason A")}})
983		if first.Results[0].Status != StatusRefundSuccess {
984			t.Fatalf("first: %+v", first.Results[0])
985		}
986		balAfter, _ := l.Balance("aa", "usdc")
987	
988		// 完全相同：duplicate，带原退款记录，不再入账。
989		dup, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "reason A")}})
990		d := dup.Results[0]
991		if d.Status != StatusDuplicate || d.Record == nil || d.Record.Seq != 1 ||
992			d.SettlementID != "p1" || d.Charged != 100 || d.Account != "aa" || d.Asset != "usdc" {
993			t.Fatalf("duplicate refund: %+v", d)
994		}
995		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
996			t.Fatalf("duplicate changed balance: %d vs %d", bal, balAfter)
997		}
998	
999		// 原因不同 / 目标不同：conflict。
1000		for i, req := range []RefundRequest{
1001			refundReq("r1", "p1", "reason B"),
1002			refundReq("r1", "p2", "reason A"),
1003		} {
1004			res, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{req}})
1005			if res.Results[0].Status != StatusConflict {
1006				t.Fatalf("case %d want conflict, got %+v", i, res.Results[0])
1007			}
1008		}
1009		snap, _ := l.Query()
1010		if len(snap.Refunds) != 1 {
1011			t.Fatalf("conflict must not add refund records: %+v", snap.Refunds)
1012		}
1013		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
1014			t.Fatalf("conflict changed balance: %d vs %d", bal, balAfter)
1015		}
1016	}
