1431	// 损坏检测：退款成功顺序中的 after_seq 必须单调不减——付款历史只会追加，
1432	// 后一笔退款落账时已存在的结算不可能比前一笔退款时更少。
1433	func TestRefundAfterSeqRegressionRejected(t *testing.T) {
1434		k := balanceKey{"aa", "usdc"}
1435		initial := map[balanceKey]int64{k: 1000}
1436		p1 := Record{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 100, Seq: 1}
1437		p2 := Record{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 2, FeeBps: 0, Fee: 0, Charged: 100, Seq: 2}
1438		rf := func(id, sid string, afterSeq, seq int64) RefundRecord {
1439			return RefundRecord{ID: id, SettlementID: sid, Reason: "x", Account: "aa", Asset: "usdc", Amount: 100, Fee: 0, Charged: 100, AfterSeq: afterSeq, Seq: seq}
1440		}
1441		finalBack := map[balanceKey]int64{k: 1000} // 两笔各 100 全部退回
1442	
1443		// 任务示例：r1（seq 1）在已有 2 笔付款时退回 p2（after_seq=2），
1444		// r2（seq 2）却声称自己落账时只有 1 笔付款（after_seq=1）。
1445		// 金额、目标、各自序号与最终余额单独都能核对上，仍必须拒绝。
1446		err := validateAndReplay(initial, finalBack, []Record{p1, p2},
1447			[]RefundRecord{rf("r1", "p2", 2, 1), rf("r1-target", "p1", 1, 2)})
1448		if KindOf(err) != ErrCorrupt {
1449			t.Fatalf("regressing after_seq: want ErrCorrupt, got %v", err)
1450		}
1451		le := err.(*LedgerError)
1452		if !strings.Contains(le.Message, `"r1-target"`) || !strings.Contains(le.Message, `"r1"`) {
1453			t.Fatalf("error must name both adjacent refunds, got %q", le.Message)
1454		}
1455	
1456		// 规则针对整本账本的付款历史：两笔退款属于不同账户/资产同样不放行。
1457		kb := balanceKey{"bb", "usdc"}
1458		pb1 := Record{ID: "pb1", Account: "bb", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 100, Seq: 2}
1459		crossInitial := map[balanceKey]int64{k: 1000, kb: 1000}
1460		crossFinal := map[balanceKey]int64{k: 1000, kb: 1000}
1461		rfb := rf("rb", "pb1", 2, 1)
1462		rfb.Account = "bb"
1463		rfa := rf("ra", "p1", 1, 2)
1464		if err := validateAndReplay(crossInitial, crossFinal, []Record{p1, pb1},
1465			[]RefundRecord{rfb, rfa}); KindOf(err) != ErrCorrupt {
1466			t.Fatalf("cross-account regression: want ErrCorrupt, got %v", err)
1467		}
1468	
1469		// 相邻退款 after_seq 相等合法：两次退款之间没有新增成功付款。
1470		if err := validateAndReplay(initial, finalBack, []Record{p1, p2},
1471			[]RefundRecord{rf("r1", "p1", 2, 1), rf("r2", "p2", 2, 2)}); err != nil {
1472			t.Fatalf("equal after_seq must be accepted: %v", err)
1473		}
1474	
1475		// 正常交错历史：付款→退款→再付款→再退款，after_seq 递增。
1476		if err := validateAndReplay(initial, finalBack, []Record{p1, p2},
1477			[]RefundRecord{rf("r1", "p1", 1, 1), rf("r2", "p2", 2, 2)}); err != nil {
1478			t.Fatalf("interleaved history must be accepted: %v", err)
1479		}
1480	}
