1527	// 旧版账本（没有 refunds 字段）无需转换即可查询、付款和退款；
1528	// 读取与仅付款都不改写文件（保持无 refunds 键），首次退款才引入该字段。
1529	func TestLegacyFileWithoutRefundsField(t *testing.T) {
1530		// 按磁盘文档规范字段顺序构造一个带合法 checksum 的旧版文档。
1531		legacy := func(balance int64, records ...Record) []byte {
1532			type doc struct {
1533				Version     int           `json:"version"`
1534				Initial     []BalanceView `json:"initial_balances"`
1535				Balances    []BalanceView `json:"balances"`
1536				Settlements []Record      `json:"settlements"`
1537			}
1538			d := doc{
1539				Version:     1,
1540				Initial:     []BalanceView{{Account: "aa", Asset: "usdc", Balance: 1000}},
1541				Balances:    []BalanceView{{Account: "aa", Asset: "usdc", Balance: balance}},
1542				Settlements: records,
1543			}
1544			payload, err := json.Marshal(d)
1545			if err != nil {
1546				t.Fatal(err)
1547			}
1548			sum := checksumHex(payload)
1549			return append(append(payload[:len(payload)-1], []byte(`,"checksum":"`+sum+`"}`)...), '\n')
1550		}
1551		rec := Record{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 300, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 300, Seq: 1}
1552		path := filepath.Join(t.TempDir(), "old.json")
1553		if err := os.WriteFile(path, legacy(700, rec), 0o600); err != nil {
1554			t.Fatal(err)
1555		}
1556	
1557		l := openOrFail(t, path)
1558		snap, err := l.Query()
1559		if err != nil {
1560			t.Fatalf("query legacy: %v", err)
1561		}
1562		if len(snap.Refunds) != 0 || snap.Balances[0].Balance != 700 {
1563			t.Fatalf("legacy query: %+v", snap)
1564		}
1565	
1566		// 再付款一笔：无退款，文件必须保持不含 refunds 键。
1567		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p2", "aa", "usdc", 100)}}); err != nil {
1568			t.Fatal(err)
1569		}
1570		if data, _ := os.ReadFile(path); bytes.Contains(data, []byte(`"refunds"`)) {
1571			t.Fatalf("submit on refund-less ledger must not add refunds key:\n%s", data)
1572		}
1573	
1574		// 首次退款引入 refunds 键并全额回到 900（700-100+300）。
1575		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "legacy")}})
1576		if err != nil {
1577			t.Fatal(err)
1578		}
1579		if rr.Results[0].Status != StatusRefundSuccess || rr.Results[0].Charged != 300 {
1580			t.Fatalf("legacy refund: %+v", rr.Results[0])
1581		}
1582		data, _ := os.ReadFile(path)
1583		if !bytes.Contains(data, []byte(`"refunds"`)) {
1584			t.Fatalf("refund must persist refunds key:\n%s", data)
1585		}
1586		if bal, _ := l.Balance("aa", "usdc"); bal != 900 {
1587			t.Fatalf("balance after legacy refund=%d want 900", bal)
1588		}
1589	
1590		// 关闭重开（新进程语义）应正常恢复付款→退款→付款账本。
1591		if err := l.Close(); err != nil {
1592			t.Fatal(err)
1593		}
1594		l2 := openOrFail(t, path)
1595		snap2, _ := l2.Query()
1596		if len(snap2.Settlements) != 2 || len(snap2.Refunds) != 1 {
1597			t.Fatalf("reopen legacy: %+v", snap2)
1598		}
1599		if bal, _ := l2.Balance("aa", "usdc"); bal != 900 {
1600			t.Fatalf("reopen balance=%d want 900", bal)
1601		}
1602	}
