1793	func TestChargeLimitPerSubmissionAndIdempotency(t *testing.T) {
1794		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 10000}})
1795		l := openOrFail(t, path)
1796	
1797		// 第一次提交：上限 100，p1 用满。
1798		res, err := l.Submit(FeeBatch{
1799			FeeBps:  0,
1800			Limits:  []ChargeLimit{limit("aa", "usdc", 100)},
1801			Intents: []PaymentIntent{intent("p1", "aa", "usdc", 100)},
1802		})
1803		if err != nil || res.Results[0].Status != StatusSettled {
1804			t.Fatalf("first submit: %v %+v", err, res.Results[0])
1805		}
1806	
1807		// 重复提交已成功付款：即使不带限额（或额度已用完）仍返回 duplicate 及原记录。
1808		res, err = l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p1", "aa", "usdc", 100)}})
1809		if err != nil {
1810			t.Fatal(err)
1811		}
1812		if res.Results[0].Status != StatusDuplicate || res.Results[0].Record == nil || res.Results[0].Record.Charged != 100 {
1813			t.Fatalf("duplicate after limit batch: %+v", res.Results[0])
1814		}
1815		// 限额变化不属于付款字段变化：带不同限额重复提交仍是 duplicate。
1816		res, err = l.Submit(FeeBatch{
1817			FeeBps:  0,
1818			Limits:  []ChargeLimit{limit("aa", "usdc", 1)},
1819			Intents: []PaymentIntent{intent("p1", "aa", "usdc", 100)},
1820		})
1821		if err != nil {
1822			t.Fatal(err)
1823		}
1824		if res.Results[0].Status != StatusDuplicate {
1825			t.Fatalf("limits must not affect idempotency: %+v", res.Results[0])
1826		}
1827	
1828		// 额度按提交从零计算：新批次同样的上限可再扣 100，历史扣款不占额度。
1829		res, err = l.Submit(FeeBatch{
1830			FeeBps:  0,
1831			Limits:  []ChargeLimit{limit("aa", "usdc", 100)},
1832			Intents: []PaymentIntent{intent("p2", "aa", "usdc", 100)},
1833		})
1834		if err != nil || res.Results[0].Status != StatusSettled {
1835			t.Fatalf("limit must reset per submission: %v %+v", err, res.Results[0])
1836		}
1837	
1838		// 退款不回补本次额度：第三次提交内 p3 用满后，即使此前 p1 已退款，
