386	
387	// 批次级错误：非法费率、非法限额（空意图也检查）整批拒绝，不产生部分结果；
388	// 合法空批次返回带预览标记的空结果列表，JSON 形如 {"dry_run":true,"results":[]}。
389	func TestPreviewBatchValidationAndEmpty(t *testing.T) {
390		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 10}})
391		l := openOrFail(t, path)
392	
393		for _, bps := range []int{-1, 10001} {
394			if _, err := l.Preview(FeeBatch{FeeBps: bps, Intents: []PaymentIntent{intent("x", "aa", "usdc", 1)}}); KindOf(err) != ErrInvalid {
395				t.Fatalf("bps=%d want ErrInvalid, got %v", bps, err)
396			}
397		}
398		badLimits := [][]ChargeLimit{
399			{limit("", "usdc", 1)},
400			{{Account: "aa", Asset: "usdc"}}, // 缺 max_charged
401			{limit("aa", "usdc", -1)},
402			{limit("aa", "usdc", 1), limit("aa", "usdc", 2)},
403		}
404		for i, lim := range badLimits {
405			// 空意图列表同样检查限额。
406			if _, err := l.Preview(FeeBatch{FeeBps: 0, Limits: lim}); KindOf(err) != ErrInvalid {
407				t.Fatalf("case %d empty intents want ErrInvalid, got %v", i, err)
408			}
409			if _, err := l.Preview(FeeBatch{FeeBps: 0, Limits: lim, Intents: []PaymentIntent{intent("p", "aa", "usdc", 1)}}); KindOf(err) != ErrInvalid {
410				t.Fatalf("case %d want ErrInvalid, got %v", i, err)
411			}
412		}
413	
414		// 合法空批次：dry_run 标记 + 空列表。
415		res, err := l.Preview(FeeBatch{FeeBps: 0, Intents: nil})
416		if err != nil {
417			t.Fatal(err)
418		}
419		if !res.DryRun || len(res.Results) != 0 {
420			t.Fatalf("empty preview: %+v", res)
421		}
422		data, err := json.Marshal(res)
423		if err != nil {
424			t.Fatal(err)
425		}
426		if string(data) != `{"dry_run":true,"results":[]}` {
427			t.Fatalf("empty preview json=%s", data)
428		}
429	}
430	
431	// 手续费、溢出、状态规则与真实提交一致。
432	func TestPreviewFeeOverflowAndState(t *testing.T) {
433		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: math.MaxInt64}})
434		l := openOrFail(t, path)
435	
436		// 1500×30bp = 4，记录携带费率/手续费/扣款。
437		res, _ := l.Preview(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{intent("p", "aa", "usdc", 1500)}})
438		r := res.Results[0]
439		if r.Status != StatusSettled || r.Record.Fee != 4 || r.Record.Charged != 1504 || r.Record.FeeBps != 30 {
440			t.Fatalf("fee preview: %+v", r)
441		}
442		// amount+fee 溢出 int64：invalid_parameter，不占序号。
443		res, _ = l.Preview(FeeBatch{FeeBps: 1, Intents: []PaymentIntent{intent("big", "aa", "usdc", math.MaxInt64)}})
444		if res.Results[0].Status != StatusInvalid || !strings.Contains(res.Results[0].Reason, "overflows") {
445			t.Fatalf("overflow preview: %+v", res.Results[0])
446		}
447		// 非 pending：state_error。
448		bad := intent("s", "aa", "usdc", 1)
449		bad.State = "failed"
450		res, _ = l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{bad}})
451		if res.Results[0].Status != StatusState {
452			t.Fatalf("state preview: %+v", res.Results[0])
453		}
454		// 预览不留任何记录。
455		snap, _ := l.Query()
456		if len(snap.Settlements) != 0 {
457			t.Fatalf("preview left records: %+v", snap.Settlements)
458		}
459	}
460	
461	// 账本不存在或损坏时沿用现有错误分类，预览不创建或修复账本。
462	func TestPreviewLedgerErrors(t *testing.T) {
463		missing := filepath.Join(t.TempDir(), "nope.json")
464		if _, err := Open(missing); KindOf(err) != ErrNotInit {
465			t.Fatalf("missing ledger: %v", err)
466		}
467		if _, err := os.Stat(missing); !os.IsNotExist(err) {
468			t.Fatalf("open missing ledger must not create a file")
469		}
470	
471		corrupt := filepath.Join(t.TempDir(), "corrupt.json")
472		if err := os.WriteFile(corrupt, []byte(`{"version":1,`), 0o600); err != nil {
473			t.Fatal(err)
474		}
475		l, err := Open(corrupt)
476		if KindOf(err) != ErrCorrupt {
477			t.Fatalf("corrupt ledger: %v", err)
478		}
479		if l != nil {
480			t.Fatalf("corrupt open returned a handle")
481		}
482	}
483

