279		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{bad`); r.code != 1 ||
280			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
281			t.Fatalf("bad refund json: code=%d err=%s", r.code, r.err)
282		}
