795	func TestCLISubmitDryRun(t *testing.T) {
796		ledgerPath := t.TempDir() + "/ledger.json"
797		if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
798			`{"balances":[{"account":"aa-1","asset":"usdc","balance":100}]}`); r.code != 0 {
799			t.Fatalf("init: %s", r.err)
800		}
801	
802		// 规格示例：余额 100、费率 0，依次 70 与 40 —— 首项成功、次项余额不足。
803		batch := `{"fee_bps":0,"intents":[
804		  {"id":"p1","account":"aa-1","asset":"usdc","amount":70},
805		  {"id":"p2","account":"aa-1","asset":"usdc","amount":40}
806		]}`
807		r := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, batch)
808		if r.code != 0 {
809			t.Fatalf("dry-run code=%d err=%s", r.code, r.err)
810		}
811		var res struct {
812			DryRun  bool `json:"dry_run"`
813			Results []struct {
814				ID     string `json:"id"`
815				Status string `json:"status"`
816				Record *struct {
817					Seq     int64 `json:"seq"`
818					Charged int64 `json:"charged"`
819				} `json:"record"`
820			} `json:"results"`
821		}
822		if err := json.Unmarshal([]byte(r.out), &res); err != nil {
823			t.Fatalf("decode: %v\n%s", err, r.out)
824		}
825		if !res.DryRun {
826			t.Fatalf("dry-run output must carry dry_run=true: %s", r.out)
827		}
828		want := []string{"settled", "insufficient_balance"}
829		if len(res.Results) != len(want) {
830			t.Fatalf("got %d results", len(res.Results))
831		}
832		for i, x := range res.Results {
833			if x.Status != want[i] {
834				t.Fatalf("item %d=%s want %s", i, x.Status, want[i])
835			}
836		}
837		if res.Results[0].Record == nil || res.Results[0].Record.Seq != 1 || res.Results[0].Record.Charged != 70 {
838			t.Fatalf("predicted record: %+v", res.Results[0].Record)
839		}
840		if res.Results[1].Record != nil {
841			t.Fatalf("failed item must not carry a record")
842		}
843		firstOut := r.out // query 会复用 r，先保存首次预览输出
844	
845		// 预览不写账本：余额仍为 100，没有任何结算记录，文件未变。
846		r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
847		var snap struct {
848			Balances    []struct{ Balance int64 } `json:"balances"`
849			Settlements []any                     `json:"settlements"`
850		}
851		if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
852			t.Fatal(err)
853		}
854		if len(snap.Balances) != 1 || snap.Balances[0].Balance != 100 || len(snap.Settlements) != 0 {
855			t.Fatalf("ledger changed by dry-run: %+v", snap)
856		}
857	
858		// 再次预览结果一致（确定性）。
859		r2 := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, batch)
860		if r2.out != firstOut {
861			t.Fatalf("repeated dry-run differs:\n%s\n%s", firstOut, r2.out)
862		}
863	
864		// 随后真实提交仍按首次提交处理：p1 成功（非 duplicate），余额变 30。
865		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, batch)
866		if r.code != 0 {
867			t.Fatalf("real submit: %s", r.err)
868		}
869		if strings.Contains(r.out, "dry_run") {
870			t.Fatalf("real submit must not carry dry_run marker: %s", r.out)
871		}
872		var sub struct {
873			Results []struct {
874				ID     string `json:"id"`
875				Status string `json:"status"`
876			} `json:"results"`
877		}
878		if err := json.Unmarshal([]byte(r.out), &sub); err != nil {
879			t.Fatal(err)
880		}
881		if sub.Results[0].Status != "settled" || sub.Results[1].Status != "insufficient_balance" {
882			t.Fatalf("real submit must be first-time: %+v", sub.Results)
883		}
884		r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
885		if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
886			t.Fatal(err)
887		}
888		if snap.Balances[0].Balance != 30 || len(snap.Settlements) != 1 {
889			t.Fatalf("after real submit: %+v", snap)
890		}
891	}
